  "recovered_c": "uint64_t fn_13(const uint8_t *in, size_t len, uint64_t arg, uint8_t *out, size_t out_cap) {\n  if (out_cap < len) {\n    return VERA_ERR;\n  }\n\n  uint8_t k[8];\n  uint8_t s[256];\n  uint8_t j = 0;\n  uint8_t i = 0;\n  uint8_t t;\n\n  for (size_t i = 0; i < 8; i++) {\n    k[i] = (uint8_t)(arg >> ((byte)(i << 3) & 0x3f));\n  }\n\n  for (size_t i = 0; i < 0x100; i++) {\n    s[i] = (uint8_t)i;\n  }\n\n  for (size_t i = 0; i < 0x100; i++) {\n    j = (k[i & 7] ^ i) + s[i] + j & 0xff;\n    t = s[i];\n    s[i] = s[j];\n    s[j] = t;\n  }\n\n  j = 0;\n  for (size_t n = 0; n < len; n++) {\n    i = (i + 1) & 0xff;\n    j = (j + s[i]) & 0xff;\n    t = s[i];\n    s[i] = s[j];\n    s[j] = t;\n    out[n] = in[n] ^ s[(uint)s[j] + (uint)s[i] & 0xff];\n  }\n\n  return len;\n}"
}
